from math11_answer_authoring import Author,RULES,step,S
A=Author(1);I=S.I;R=S.Rational;rt=S.sqrt;a,b=S.symbols('a b',real=True);z,w=S.symbols('z w')
A.put('1.2','1','',r'$z_1+z_2=z_2+z_1=3$; $z_1z_2=z_2z_1=3-i$',[RULES['verify'],step('Addition gives the same sum in either order.','دونوں ترتیبوں میں جمع کا حاصل یکساں ہے۔','په دواړو ترتیبونو کې د جمع پایله یو شان ده.',r'(2+i)+(1-i)=(1-i)+(2+i)=3'),step('Multiplication gives the same product in either order.','دونوں ترتیبوں میں ضرب کا حاصل یکساں ہے۔','په دواړو ترتیبونو کې د ضرب پایله یو شان ده.',r'(2+i)(1-i)=(1-i)(2+i)=3-i')])
assert S.expand((2+I)*(1-I))==3-I
A.put('1.2','2','',r'$(z_1+z_2)+z_3=z_1+(z_2+z_3)=4+2i$; $(z_1z_2)z_3=z_1(z_2z_3)=-17+7i$',[RULES['verify'],step('Calculate the inner pairs first, then finish each side.','پہلے قوسین کے اندر کے جوڑوں کی قیمت معلوم کریں، پھر ہر طرف کا حساب مکمل کریں۔','لومړی د قوسونو دننه جوړې محاسبه کړئ، بیا د هرې خوا حساب بشپړ کړئ.',r'\begin{aligned}(2-i)+(2+3i)&=(-1+i)+(5+i)=4+2i\\(-1+5i)(2+3i)&=(-1+i)(12+5i)=-17+7i\end{aligned}')])
assert S.expand((-1+I)*(3-2*I)*(2+3*I))==-17+7*I
v=S.expand((rt(3)+rt(2)*I)*(rt(2)-rt(3)*I+2-2*I))
expected=2*rt(6)+2*rt(3)+2*rt(2)+(-1+2*rt(2)-2*rt(3))*I
assert S.simplify(v-expected)==0
A.put('1.2','3','',r'$z_1(z_2+z_3)=z_1z_2+z_1z_3=2\sqrt6+2\sqrt3+2\sqrt2+(-1+2\sqrt2-2\sqrt3)i$',[RULES['verify'],step('Expand each side. The real and imaginary parts agree.','ہر طرف کو کھولیں۔ حقیقی اور خیالی حصے برابر ہیں۔','هره خوا پراخه کړئ. حقیقي او خیالي برخې برابرې دي.',r'\begin{aligned}z_1z_2&=2\sqrt6-i\\z_1z_3&=2\sqrt3+2\sqrt2+(2\sqrt2-2\sqrt3)i\\z_1(z_2+z_3)&=2\sqrt6+2\sqrt3+2\sqrt2+(-1+2\sqrt2-2\sqrt3)i\end{aligned}')])
for p,x,y in [('(i)',5,2),('(ii)',7,-9)]:
    value=x+y*I;inv=S.expand_complex(1/value);assert S.simplify(value*inv)==1
    add='$'+S.latex(-value)+'$';mul='$'+S.latex(inv)+'$'
    A.put('1.2','4',p,f'Additive: {add}; multiplicative: {mul}',[step(r'The additive inverse is $-z$. For $z\ne0$, the multiplicative inverse is $\bar z/|z|^2$.',r'جمعی معکوس $-z$ ہے۔ $z\ne0$ کے لیے ضربی معکوس $\bar z/|z|^2$ ہے۔',r'د جمع معکوس $-z$ دی. د $z\ne0$ لپاره د ضرب معکوس $\bar z/|z|^2$ دی.',fr'-z={S.latex(-value)},\qquad z^{{-1}}={S.latex(inv)}')],answerUr=f'جمعی: {add}؛ ضربی: {mul}',answerPs=f'د جمع: {add}؛ د ضرب: {mul}')
A.calc('1.2','5','(i)',S.conjugate(2+4*I+1-3*I),3-I,'verify',r'\overline{(2+4i)+(1-3i)}=3-i=(2-4i)+(1+3i)')
A.calc('1.2','5','(ii)',S.conjugate((2+3*I)*(2-3*I)),13,'verify',r'\overline{(2+3i)(2-3i)}=13=(2-3i)(2+3i)')
expected=(-2*a*a+9*b*b+9*a*b*I)/(4*a*a+9*b*b)
assert S.simplify(S.conjugate((-a-3*b*I)/(2*a-3*b*I))-expected)==0
A.put('1.2','5','(iii)',r'$\overline{z_1/z_2}=\bar z_1/\bar z_2=\dfrac{-2a^2+9b^2+9abi}{4a^2+9b^2}$; $(a,b)\ne(0,0)$.',[RULES['divide'],step('For real $a,b$, the denominator is nonzero except at $a=b=0$. Both calculations give the same result.','حقیقی $a,b$ کے لیے مخرج صرف $a=b=0$ پر صفر ہے۔ دونوں حساب ایک ہی نتیجہ دیتے ہیں۔','د حقیقي $a,b$ لپاره مخرج یوازې په $a=b=0$ کې صفر دی. دواړه محاسبې یو شان پایله ورکوي.',r'\overline{\frac{-a-3bi}{2a-3bi}}=\overline{\frac{-2a^2+9b^2-9abi}{4a^2+9b^2}}=\frac{-a+3bi}{2a+3bi}=\frac{-2a^2+9b^2+9abi}{4a^2+9b^2}')])
for p,ans,work in [('(i)',r'$|z_1z_2|=|z_1||z_2|$',r'|z_1z_2|^2=(z_1z_2)\overline{z_1z_2}=(z_1\bar z_1)(z_2\bar z_2)=|z_1|^2|z_2|^2'),('(ii)',r'$|z_1/z_2|=|z_1|/|z_2|,\quad z_2\ne0$',r'\left|\frac{z_1}{z_2}\right|^2=\frac{z_1\bar z_1}{z_2\bar z_2}=\frac{|z_1|^2}{|z_2|^2}')]:
    A.put('1.2','6',p,ans,[step(r'Square each modulus and use $|z|^2=z\bar z$.',r'ہر مقیاس کا مربع لیں اور $|z|^2=z\bar z$ استعمال کریں۔',r'د هر مقیاس مربع واخلئ او $|z|^2=z\bar z$ وکاروئ.',work),step('Take the nonnegative square root of both sides.','دونوں طرف غیر منفی مربع جذر لیں۔','د دواړو خواوو نامنفي مربع جذر واخلئ.')])
for p,e,re,im,work in [('(i)',(2+3*I)/(5-2*I),R(4,29),R(19,29),r'\frac{(2+3i)(5+2i)}{29}=\frac4{29}+\frac{19}{29}i'),('(ii)',(1+2*I)**2/(1-3*I),-R(3,2),-R(1,2),r'\frac{(-3+4i)(1+3i)}{10}=-\frac32-\frac12i'),('(iii)',(1-I)/(1+I)**2,-R(1,2),-R(1,2),r'\frac{1-i}{2i}=-\frac12-\frac12i'),('(iv)',(2*a-b*I)**-2,(4*a*a-b*b)/(4*a*a+b*b)**2,4*a*b/(4*a*a+b*b)**2,r'\frac{(2a+bi)^2}{(4a^2+b^2)^2}=\frac{4a^2-b^2}{(4a^2+b^2)^2}+\frac{4ab}{(4a^2+b^2)^2}i'),('(v)',((3+4*I)/(4-3*I))**-2,-1,0,r'\left(\frac{3+4i}{4-3i}\right)^{-2}=i^{-2}=-1'),('(vi)',((4-5*I)/(2+3*I))**2,-R(435,169),R(308,169),r'\left(\frac{-7-22i}{13}\right)^2=-\frac{435}{169}+\frac{308}{169}i')]:
    A.calc('1.2','7',p,e,re+im*I,'parts',work)
    A.answers[f'1.2|7|{p}']['answer']=fr'$Re={S.latex(re)},\quad Im={S.latex(im)}$'
    if p=='(iv)':A.answers[f'1.2|7|{p}']['steps'].append(step(r'Require $(a,b)\ne(0,0)$.',r'$(a,b)\ne(0,0)$ لازم ہے۔',r'$(a,b)\ne(0,0)$ اړین دی.'))
for p,ans,work in [('(i)',r'$z+\bar z=2Re(z)$',r'(a+bi)+(a-bi)=2a'),('(ii)',r'$z-\bar z=2iIm(z)$',r'(a+bi)-(a-bi)=2bi'),('(iii)',r'$z\bar z=[Re(z)]^2+[Im(z)]^2$',r'(a+bi)(a-bi)=a^2+b^2'),('(iv)',r'$z=\bar z\Rightarrow Im(z)=0$',r'a+bi=a-bi\ \Rightarrow\ 2bi=0\ \Rightarrow\ b=0')]:
    A.put('1.2','8',p,ans,[step(r'Let $z=a+bi$ with real $a,b$, so $\bar z=a-bi$.',r'فرض کریں حقیقی $a,b$ کے لیے $z=a+bi$، پس $\bar z=a-bi$ ہے۔',r'فرض کړئ د حقیقي $a,b$ لپاره $z=a+bi$ دی، نو $\bar z=a-bi$ دی.',work)])
A.put('1.2','8','(v)',r'$\bar z=-z\iff Re(z)=0$. If pure imaginary excludes zero, require $z\ne0$.',[step('Write $z=a+bi$. The condition forces $a=0$, and every $bi$ satisfies it.','$z=a+bi$ لکھیں۔ شرط سے $a=0$ آتا ہے، اور ہر $bi$ اسے پورا کرتا ہے۔','$z=a+bi$ ولیکئ. له شرط څخه $a=0$ راځي، او هر $bi$ دا شرط پوره کوي.',r'a-bi=-a-bi\iff 2a=0'),step(r'Clarification: zero also satisfies the equation. If a pure imaginary number must have nonzero imaginary part, the statement needs the extra assumption $z\ne0$.',r'وضاحت: صفر بھی مساوات کو پورا کرتا ہے۔ اگر خالص خیالی عدد کا خیالی حصہ غیر صفر ہونا ضروری ہو تو بیان میں اضافی شرط $z\ne0$ درکار ہے۔',r'روښانتیا: صفر هم معادله پوره کوي. که د خالص خیالي عدد خیالي برخه باید غیرصفر وي، بیان اضافي شرط $z\ne0$ ته اړتیا لري.')],answerUr=r'$\bar z=-z\iff Re(z)=0$۔ اگر خالص خیالی میں صفر شامل نہ ہو تو $z\ne0$ درکار ہے۔',answerPs=r'$\bar z=-z\iff Re(z)=0$. که خالص خیالي صفر نه رانغاړي، $z\ne0$ اړین دی.')
for p,part,n in [('(i)','Re',3),('(ii)','Im',2)]:
    A.put('1.2','9',p,fr'$-\sqrt{{13}}\le {n}\le\sqrt{{13}}$',[RULES['modulus'],step('Compute the modulus and compare the component with its bounds.','مقیاس معلوم کریں اور متعلقہ حصے کا اس کی حدوں سے موازنہ کریں۔','مقیاس محاسبه کړئ او اړونده برخه له حدونو سره پرتله کړئ.',fr'|3+2i|=\sqrt{{13}},\quad {part}(z)={n},\quad {n}^2\le13')])
systems=[('(i)',[z-4*w-3*I,2*z+3*w-11+5*I],4-I,1-I,r'z=4w+3i,\quad11w=11-11i'),('(ii)',[z+w-3*I,2*z+3*w-2],-2+9*I,2-6*I,r'z=3i-w,\quad w=2-6i'),('(iii)',[3*z+(2+I)*w-11+I,(2-I)*z-w+1-I],1,3-2*I,r'w=(2-i)z+1-i,\quad8z=8')]
for p,eqs,zv,wv,work in systems:
    assert all(S.expand(e.subs({z:zv,w:wv}))==0 for e in eqs)
    A.put('1.3','1',p,fr'$z={S.latex(zv)},\quad w={S.latex(wv)}$',[step('Isolate one unknown and substitute into the other equation.','ایک نامعلوم کو الگ کریں اور دوسری مساوات میں رکھیں۔','یو مجهول جلا او په بلې معادلې کې یې ځای پر ځای کړئ.',work),step('Back-substitute to find the other unknown. Both original equations are satisfied.','واپس قیمت رکھ کر دوسرا نامعلوم معلوم کریں۔ دونوں اصل مساواتیں پوری ہوتی ہیں۔','بېرته ارزښت ځای پر ځای کړئ او بل مجهول ومومئ. دواړه اصلي معادلې پوره کېږي.',fr'z={S.latex(zv)},\quad w={S.latex(wv)}')])
factors=[('(i)',z**3+6*z+20,(z+2)*(z-1-3*I)*(z-1+3*I),r'(z+2)(z^2-2z+10)=(z+2)(z-1-3i)(z-1+3i)'),('(ii)',3*z*z+7,3*(z-I*rt(21)/3)*(z+I*rt(21)/3),r'3(z-i\sqrt{7/3})(z+i\sqrt{7/3})'),('(iii)',z*z+4,(z-2*I)*(z+2*I),r'(z-2i)(z+2i)'),('(iv)',z**3-2*z*z+z-2,(z-2)*(z-I)*(z+I),r'z^2(z-2)+(z-2)=(z-2)(z^2+1)=(z-2)(z-i)(z+i)')]
for p,poly,f,work in factors:
    assert S.expand(poly-f)==0
    A.put('1.3','2',p,'$'+S.latex(f)+'$',[RULES['factor'],step('Multiplying the linear factors reproduces the original polynomial.','خطی اجزا کو ضرب دینے سے اصل کثیر رقمی حاصل ہوتا ہے۔','د خطي عواملو په ضربولو اصلي څو حدي بېرته ترلاسه کېږي.',work)])
for q,poly,vals,work in [('3',z*z+2*z+2,[-1+I,-1-I],r'(-1\pm i)^2+2(-1\pm i)+2=(\mp2i)+(-2\pm2i)+2=0'),('4',z*z-2*z+5,[1+2*I],r'(1+2i)^2-2(1+2i)+5=(-3+4i)-2-4i+5=0')]:
    assert all(S.expand(poly.subs(z,v))==0 for v in vals)
    en=('$z=-1+i$ and $z=-1-i$ both satisfy the equation.' if q=='3' else 'Yes. $z=1+2i$ is a solution.')
    ur=('$z=-1+i$ اور $z=-1-i$ دونوں مساوات کو پورا کرتے ہیں۔' if q=='3' else 'جی ہاں۔ $z=1+2i$ حل ہے۔')
    ps=('$z=-1+i$ او $z=-1-i$ دواړه معادله پوره کوي.' if q=='3' else 'هو. $z=1+2i$ یو حل دی.')
    A.put('1.3',q,'',en,[RULES['substitute'],step('The substituted expression equals zero.','قیمت رکھنے سے عبارت صفر بنتی ہے۔','د ارزښت په ځای پر ځای کولو عبارت صفر کېږي.',work)],answerUr=ur,answerPs=ps)
roots=[('5','(i)',z*z+z+3,[(-1+I*rt(11))/2,(-1-I*rt(11))/2],r'z=\frac{-1\pm\sqrt{1-12}}2=\frac{-1\pm i\sqrt{11}}2'),('5','(ii)',z*z-z-1,[(1+rt(5))/2,(1-rt(5))/2],r'z^2-z-1=0\Rightarrow z=\frac{1\pm\sqrt5}2'),('5','(iii)',z*z-2*z+I,[1+S.sqrt(1-I),1-S.sqrt(1-I)],r'(z-1)^2=1-i\Rightarrow z=1\pm\sqrt{1-i}'),('5','(iv)',z*z+4,[2*I,-2*I],r'z^2=-4\Rightarrow z=\pm2i'),('6','(i)',z**4+z*z+1,[(1+I*rt(3))/2,(1-I*rt(3))/2,(-1+I*rt(3))/2,(-1-I*rt(3))/2],r'z^4+z^2+1=(z^2+z+1)(z^2-z+1)=0'),('6','(ii)',z**3+8,[-2,1+I*rt(3),1-I*rt(3)],r'z^3+8=(z+2)(z^2-2z+4)=0'),('6','(iii)',(z-1)**3+1,[0,R(3,2)+I*rt(3)/2,R(3,2)-I*rt(3)/2],r'(z-1)^3+1=z(z^2-3z+3)=0'),('6','(iv)',z**3-1,[1,(-1+I*rt(3))/2,(-1-I*rt(3))/2],r'z^3-1=(z-1)(z^2+z+1)=0')]
for q,p,poly,vals,work in roots:
    assert len(vals)==S.degree(poly,z)
    assert all(S.simplify(S.expand(poly.subs(z,v)))==0 for v in vals),(q,p)
    final=r',\quad'.join(S.latex(v) for v in vals)
    A.put('1.3',q,p,'$z='+final+'$',[RULES['quadratic' if q=='5' else 'factor'],step('Solve each quadratic or linear factor. Substitution checks every root.','ہر دو درجی یا خطی جز حل کریں۔ ہر جذر کی تصدیق قیمت رکھ کر ہوتی ہے۔','هر دوه درجه یي یا خطي عامل حل کړئ. د هر جذر تصدیق په ځای پر ځای کولو کېږي.',work),step('The complete set of roots is:','تمام جذر یہ ہیں:','د ټولو جذرونو مجموعه دا ده:',fr'z\in\{{{final}\}}')])
    if q=='5' and p=='(iii)':A.answers[f'1.3|{q}|{p}']['steps'].append(step(r'For real and imaginary parts, use this principal square root. The outer $\pm$ gives both roots.',r'حقیقی اور خیالی حصوں کے لیے یہ اصلی مربع جذر استعمال کریں۔ باہر کا $\pm$ دونوں جذر دیتا ہے۔',r'د حقیقي او خیالي برخو لپاره دا اصلي مربع جذر وکاروئ. بهرنی $\pm$ دواړه جذرونه ورکوي.',r'\sqrt{1-i}=\sqrt{\frac{\sqrt2+1}{2}}-i\sqrt{\frac{\sqrt2-1}{2}}'))
A.save(['1.2','1.3'],[21,22,27])
